package com.vaijunto.controller;
import com.vaijunto.dto.*; import com.vaijunto.service.AddressService; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/addresses") @RequiredArgsConstructor public class AddressController {private final AddressService service; @GetMapping public List<AddressDto> list(Authentication a){return service.list(a.getName());} @PostMapping public ResponseEntity<AddressDto> create(@RequestBody AddressRequest r,Authentication a){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r,a.getName()));} @PutMapping("/{id}") public AddressDto update(@PathVariable UUID id,@RequestBody AddressRequest r,Authentication a){return service.update(id,r,a.getName());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable UUID id,Authentication a){service.delete(id,a.getName());return ResponseEntity.noContent().build();} @DeleteMapping("/recents") public ResponseEntity<Void> clear(Authentication a){service.clearRecents(a.getName());return ResponseEntity.noContent().build();}}
